<?php require 'header.php'; $db=db_load(); $json=[]; foreach($db['appointments'] as $a){$p=find_item($db['patients'],$a['patient_id']); $patient=$p['name']??'Patient'; if(!empty($a['date'])) $json[]=['id'=>$a['id'],'title'=>$a['time'].' - '.$patient,'start'=>$a['date'].'T'.$a['time'],'extendedProps'=>['appointment'=>$a['number']]]; if(!empty($a['next_date'])) $json[]=['id'=>$a['id'].'-next','title'=>'Next: '.($a['next_time']??'').' - '.$patient,'start'=>$a['next_date'].'T'.($a['next_time']??'00:00'),'classNames'=>['next-appointment'],'extendedProps'=>['appointment'=>$a['number'],'next'=>true,'editId'=>$a['id']]];} ?><div class="admin-top"><h1>Appointment Calendar</h1></div><div class="calendar" id="calendar"></div><script>document.addEventListener('DOMContentLoaded',()=>{const c=document.getElementById('calendar');const cal=new FullCalendar.Calendar(c,{initialView:'dayGridMonth',headerToolbar:{left:'prev,next today',center:'title',right:'dayGridMonth,timeGridWeek,timeGridDay'},height:'auto',events:<?=json_encode($json)?>,eventClick:function(info){info.jsEvent.preventDefault();window.location='appointment-edit.php?id='+encodeURIComponent(info.event.extendedProps.editId||info.event.id)}});cal.render();});</script><?php require 'footer.php'; ?>
